import react from '@vitejs/plugin-react'
import { defineConfig } from 'vite'

// In dev, /api and /health are proxied to the FastAPI orchestrator, and /cad to the CAD worker.
export default defineConfig({
  plugins: [react()],
  server: {
    proxy: {
      '/api': 'http://localhost:8000',
      '/health': 'http://localhost:8000',
      '/cad': { target: 'http://localhost:8001', rewrite: (p) => p.replace(/^\/cad/, '') },
    },
  },
})

 * alternatives found for it. */
export function RiskTable({ rows, alternatives }: { rows: RiskRow[]; alternatives: Record<string, Alternative[]> }) {
  return (
    <section className="panel">
      <h2>Supply risk by part</h2>
      <table>
        <thead>
          <tr>
            <th>Part</th>
            <th>Domain</th>
            <th>Qty</th>
            <th>Risk factors</th>
            <th>Overall</th>
          </tr>
        </thead>
        <tbody>
          {rows.map(({ line, risk }) => {
            const alts = alternatives[line.id] ?? []
            return (
              <Fragment key={line.id}>
                <tr>
                  <td>
                    {line.part}
                    {line.manufacturer && <span className="muted"> · {line.manufacturer}</span>}{' '}
                    {line.illustrative && (
                      <span className="badge badge-illustrative" title="real part of the right class, not the company's actual BOM">
                        ILLUSTRATIVE
                      </span>
                    )}
                  </td>
                  <td>{line.domain}</td>
                  <td>{line.qty}</td>
                  <td className="chips">
                    {RISK_FACTORS.map((name) => {
                      const f = risk.factors.find((x) => x.name === name)
                      return (
                        <LevelChip
                          key={name}
                          level={f?.level ?? 'unknown'}
                          title={f ? `${f.value} · ${f.reason}` : 'not assessed'}
                        >
                          {name}
                        </LevelChip>
                      )
                    })}
                  </td>
                  <td>
                    <LevelChip level={risk.overall} />
                  </td>
                </tr>
                {alts.length > 0 && (
                  <tr className="subrow">
                    <td colSpan={5}>
                      <Alternatives alts={alts} />
                    </td>
                  </tr>
                )}
              </Fragment>
            )
          })}
        </tbody>
      </table>
    </section>
  )
}
